import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-27","description":"","frontmatter":{"title":"AI 动态 · 2026-11-27","date":"2026-11-27T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-27.md","filePath":"news/2026-11/ai-news-2026-11-27.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-27.md"};function i(o,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-11-27" tabindex="-1">AI 动态 · 2026-11-27 <a class="header-anchor" href="#ai-动态-·-2026-11-27" aria-label="Permalink to &quot;AI 动态 · 2026-11-27&quot;">​</a></h1><blockquote><p>截至 2026-11-27。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>英伟达暂停向马来西亚、新加坡、泰国、印尼交付服务器，AI芯片的地缘管制从中国外溢到整个东南亚。</li><li>模型侧同一天出现多条硬进展：腾讯开源DFly2投机解码、Sakana发布30B的Namazu Small、智谱辟谣GLM-5.5延期。</li><li>工程侧焦点转向Agent落地与安全：Anthropic推出Claude Ship，1Password与PingCAP同日曝出数据泄露。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-anthropic发布claude-ship-pr合并量3个月翻倍-回滚比例降超40" tabindex="-1">头条 · Anthropic发布Claude Ship：PR合并量3个月翻倍，回滚比例降超40% <a class="header-anchor" href="#头条-·-anthropic发布claude-ship-pr合并量3个月翻倍-回滚比例降超40" aria-label="Permalink to &quot;头条 · Anthropic发布Claude Ship：PR合并量3个月翻倍，回滚比例降超40%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">雷锋网 AI</span><time datetime="2026-11-27">2026-11-27</time></p><p>Anthropic推出Claude Ship，把AI Agent的工作范围从写代码延伸到GitHub PR的完整交付流程：代码审查、自动修复CI失败、处理合并冲突与审批。架构上拆成Code Review、PR Steward、Claude Approvals三个独立组件，并用YAML策略定义代码路径、变更范围与审批要求的对应关系，避免执行、审查、审批集中在同一个Agent手里。官方数据称Claude已写下约90%代码，单日代码变更从2500增至3万，审查覆盖率升至54%，内部PR合并量3个月翻倍，回滚比例下降超40%。对读者：值得借鉴的不是让Agent多干活，而是把职责隔离与策略引擎先设计好。</p><p class="news-entry-source"><a href="https://www.leiphone.com/category/ai/iWUKWuRp4AmJ6dZE.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="_1password确认内部系统遭入侵-密码库未受影响" tabindex="-1">1Password确认内部系统遭入侵，密码库未受影响 <a class="header-anchor" href="#_1password确认内部系统遭入侵-密码库未受影响" aria-label="Permalink to &quot;1Password确认内部系统遭入侵，密码库未受影响&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-11-27">2026-11-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/84726d5a7f1e.webp" alt="配图"></p><p>1Password发布安全公告，确认攻击者通过一名员工的企业GitHub账号入侵内部系统，导致部分用户账户信息及内部源代码泄露；公司称用户的密码保险库及其中内容均未受影响。事件自11月19日开始调查，攻击者利用被入侵账号向后端服务植入恶意代码。对读者：密码管理器本身仍是可信存储，但企业侧应把GitHub账号权限、CI密钥与后端部署链路当作同一攻击面来收紧。</p><p class="news-entry-source"><a href="https://sspai.com/post/119632" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="美团三季报-营收1156亿元-ai工作台「妙手」服务200万商家" tabindex="-1">美团三季报：营收1156亿元，AI工作台「妙手」服务200万商家 <a class="header-anchor" href="#美团三季报-营收1156亿元-ai工作台「妙手」服务200万商家" aria-label="Permalink to &quot;美团三季报：营收1156亿元，AI工作台「妙手」服务200万商家&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">雷锋网 AI</span><time datetime="2026-11-27">2026-11-27</time></p><p>美团发布2026年第三季度业绩，实现收入1156亿元，同比增长21.6%，净利润同比由负转正；核心本地商业营收783亿元，同比增长16.8%，经营利润同比由负转正、同比减亏近200亿元。季度研发投入77亿元，同比增长11.3%，AI经营工作台「妙手」（CatPaw）已服务超过200万商家。对读者：本地生活赛道的AI落地更偏经营工具而非聊天入口，做B端产品的团队可关注这类「嵌入既有工作流」的路径。</p><p class="news-entry-source"><a href="https://www.leiphone.com/category/industrynews/iJ0tw7k1kHDs5zjT.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="android「create-my-widget」上手-diy小组件的vibe-coding乐趣" tabindex="-1">Android「Create My Widget」上手：DIY小组件的vibe-coding乐趣 <a class="header-anchor" href="#android「create-my-widget」上手-diy小组件的vibe-coding乐趣" aria-label="Permalink to &quot;Android「Create My Widget」上手：DIY小组件的vibe-coding乐趣&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-27">2026-11-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/3ff2fe887b47.jpg" alt="配图"></p><p>Google推出Create My Widget工具，让用户用自然语言把Android主屏变成高度可定制的小组件面板。The Verge实测后认为它确实好玩，但能力有限——作者想要的实时公交到站小组件并未实现。这代表一类新交互：把生成式能力塞进系统级小组件，而不是另开一个聊天App。对读者：若在做移动端产品，可评估把AI生成结果直接落到小组件/卡片这类「一眼可见」的界面，而非要求用户主动打开应用。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1041801/android-intelligence-create-my-widget-gemini" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepseek网页与app上线聊天账单-显示token用量与金额" tabindex="-1">DeepSeek网页与App上线聊天账单，显示Token用量与金额 <a class="header-anchor" href="#deepseek网页与app上线聊天账单-显示token用量与金额" aria-label="Permalink to &quot;DeepSeek网页与App上线聊天账单，显示Token用量与金额&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-11-27">2026-11-27</time></p><p>DeepSeek在网页端和App端的回复下方新增硬币图标，点开可看到本轮消耗额度、输入（缓存命中/未命中）与输出Token单价、用量、金额，以及上下文占用进度圈。目前聊天仍然免费，但结合此前免费用户限额的讨论，外界普遍猜测这是为后续收费做铺垫。对读者：Token级成本可视化会逐渐成为AI产品标配，做应用时提前把用量与计费埋点设计进去，比事后补账更省事。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/11/513305.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="支付宝车载助手3-0发布-从「对话智能」走向「行动智能」" tabindex="-1">支付宝车载助手3.0发布：从「对话智能」走向「行动智能」 <a class="header-anchor" href="#支付宝车载助手3-0发布-从「对话智能」走向「行动智能」" aria-label="Permalink to &quot;支付宝车载助手3.0发布：从「对话智能」走向「行动智能」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">雷锋网 AI</span><time datetime="2026-11-27">2026-11-27</time></p><p>广州车展期间，支付宝发布AI原生车载智能体「支付宝车载助手3.0」，具备车主意图体系、智能服务互联、APASS可信授权、声纹支付、Agentic端云一体五大能力，并与车企座舱主智能体协同。产品把停车缴费、加油充电、高速通行、智能外卖点单等高频服务接入座舱，主打「车内发起、车外交付」。对读者：Agent商业化的关键卡点正在从模型能力转向授权与支付闭环，值得关注可信授权这类基础设施的演进。</p><p class="news-entry-source"><a href="https://www.leiphone.com/category/industrynews/szJUnXEhChJQgJHZ.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="sakana-ai发布namazu-small-30b-a3b模型基于nemotron-3-nano" tabindex="-1">Sakana AI发布Namazu Small：30B-A3B模型基于Nemotron 3 Nano <a class="header-anchor" href="#sakana-ai发布namazu-small-30b-a3b模型基于nemotron-3-nano" aria-label="Permalink to &quot;Sakana AI发布Namazu Small：30B-A3B模型基于Nemotron 3 Nano&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-27">2026-11-27</time></p><p>Sakana AI发布Sakana Namazu Small，这是一个基于NVIDIA Nemotron 3 Nano构建的30B-A3B推理模型。官方称其在25项基准上平均得分60.1，超过120B的Nemotron 3 Super的56.2。小参数、稀疏激活在评测上反超大模型，说明后训练与数据配比仍有可观空间。对读者：选型时不要只看参数量，同尺寸下的训练配方差异可能比规模差异更决定实际表现。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/26/sakana-ai-namazu-small-30b-nemotron-3-nano/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="腾讯开源dfly2-复用目标模型稀疏kv-cache的投机解码" tabindex="-1">腾讯开源DFly2：复用目标模型稀疏KV Cache的投机解码 <a class="header-anchor" href="#腾讯开源dfly2-复用目标模型稀疏kv-cache的投机解码" aria-label="Permalink to &quot;腾讯开源DFly2：复用目标模型稀疏KV Cache的投机解码&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-27">2026-11-27</time></p><p>腾讯开源DFly2，面向稀疏注意力LLM的投机解码drafter。其每个草稿层复用目标模型的KV Cache与top-k indexer选择，不额外占用草稿KV显存，官方称可将64K上下文的服务吞吐提升最多81%。对读者：长上下文推理的成本瓶颈常在KV Cache，这类「不新增显存」的加速方案值得在自建推理服务里做小流量验证。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/26/tencent-dfly2-speculative-decoding-sparse-models/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nexos-ai推出ai-gateway-200-模型统一接入-内置预算与治理" tabindex="-1">nexos.ai推出AI Gateway：200+模型统一接入，内置预算与治理 <a class="header-anchor" href="#nexos-ai推出ai-gateway-200-模型统一接入-内置预算与治理" aria-label="Permalink to &quot;nexos.ai推出AI Gateway：200+模型统一接入，内置预算与治理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-27">2026-11-27</time></p><p>nexos.ai发布AI Adoption Platform，把200多个模型放在同一个AI Gateway之后，并内置预算限制与治理能力。多模型接入的统一网关正在成为企业采用AI的中间层，解决的不只是调用便利，还有成本可控与合规审计。对读者：若团队已在多个模型供应商之间切换，可对比自建网关与这类托管方案的运维成本，重点看预算熔断与日志留存是否满足审计要求。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/26/nexos-ai-ai-gateway-200-models-governance/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="智谱辟谣glm-5-5延期-性能fable级-万卡昇腾进展顺利" tabindex="-1">智谱辟谣GLM-5.5延期：性能Fable级，万卡昇腾进展顺利 <a class="header-anchor" href="#智谱辟谣glm-5-5延期-性能fable级-万卡昇腾进展顺利" aria-label="Permalink to &quot;智谱辟谣GLM-5.5延期：性能Fable级，万卡昇腾进展顺利&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">极客公园</span><time datetime="2026-11-27">2026-11-27</time></p><p>智谱高管杨昊翊公开辟谣，称此前流传的GLM-5.5跳票爆料均为假消息。此前有外媒称原计划12月发布的GLM-5.5将延期至2027年一季度，并称原因是海外厂商对蒸馏技术设限。国联民生研究报告称其参数量在2-3万亿之间、性能达Fable级别；用于前期训练的万卡昇腾950DT进展顺利，预计明年跑通。对读者：国产大模型的发布节奏信息噪音较大，评估时应以官方口径与实际可用API为准。</p><p class="news-entry-source"><a href="http://www.geekpark.net/news/374546" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="datasette-mcp-0-4发布-为任意datasette实例加上mcp服务" tabindex="-1">datasette-mcp 0.4发布：为任意Datasette实例加上MCP服务 <a class="header-anchor" href="#datasette-mcp-0-4发布-为任意datasette实例加上mcp服务" aria-label="Permalink to &quot;datasette-mcp 0.4发布：为任意Datasette实例加上MCP服务&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-27">2026-11-27</time></p><p>Simon Willison发布datasette-mcp 0.4，该插件可为任意Datasette实例添加 /-/mcp 的MCP服务器，本次更新主要修复与Datasette 1.0a44的兼容性。它让数据探索工具直接成为Agent可调用的工具端点，是MCP生态里典型的「小插件、大杠杆」案例。对读者：若手上已有内部数据服务，加一层MCP封装比重新做Agent集成成本低得多，可优先试点。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/27/datasette-mcp/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="在trainium3上用ltx-2-5生成视频" tabindex="-1">在Trainium3上用LTX-2.5生成视频 <a class="header-anchor" href="#在trainium3上用ltx-2-5生成视频" aria-label="Permalink to &quot;在Trainium3上用LTX-2.5生成视频&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-11-27">2026-11-27</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/ad4245004760.jpg" alt="配图"></p><p>Hugging Face博客记录了在AWS Trainium3上运行LTX-2.5视频生成模型的实践。视频生成正从GPU单一路径扩展到自研加速器，成本结构随之变化。对读者：关注非NVIDIA算力在生成式负载上的实际可用性，尤其是编译适配与吞吐数据，可作为降低推理成本的备选路线。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/video-trainium3" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="jiohotstar实测六种方案-给编码agent加知识库反而更费token" tabindex="-1">JioHotstar实测六种方案：给编码Agent加知识库反而更费Token <a class="header-anchor" href="#jiohotstar实测六种方案-给编码agent加知识库反而更费token" aria-label="Permalink to &quot;JioHotstar实测六种方案：给编码Agent加知识库反而更费Token&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-27">2026-11-27</time></p><p>JioHotstar对AI编码智能体的六种代码库理解方案做了基准测试，结论是结构化搜索在目标明确的任务中表现稳健，语义检索更适合需求模糊的场景；增加检索层并不必然提升准确率或降低Token消耗，Sourcebot在高难度任务中优于基线且成本更低，文件系统工具依然能打。对读者：别默认「上RAG就更好」，先用自己仓库的真实任务做A/B，再决定是否引入检索层。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/Ql4GGMIEqA3bI2W2lh7h?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="ricky-hanlon离开meta-但仍留在react" tabindex="-1">Ricky Hanlon离开Meta，但仍留在React <a class="header-anchor" href="#ricky-hanlon离开meta-但仍留在react" aria-label="Permalink to &quot;Ricky Hanlon离开Meta，但仍留在React&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">React Status</span><time datetime="2026-11-27">2026-11-27</time></p><p>React Status第499期报道，Ricky Hanlon在帮助React「从每周400万次下载增长到2.5亿次」之后离开Meta，并指出React核心团队大部分人已离开Meta。他将继续参与React开发，加上React今年成立了自己的基金会，这更像一个时代的结束而非项目转向。同期还包括TanStack Query v6路线图、Expo的非React应用框架等。对读者：React的治理正从单一公司主导转向基金会模式，长期项目可关注基金会章程与发布节奏的变化。</p><p class="news-entry-source"><a href="https://react.statuscode.com/issues/499" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="第一次用ai-figma-mcp开发网页的小结" tabindex="-1">第一次用AI + Figma MCP开发网页的小结 <a class="header-anchor" href="#第一次用ai-figma-mcp开发网页的小结" aria-label="Permalink to &quot;第一次用AI + Figma MCP开发网页的小结&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">张鑫旭</span><time datetime="2026-11-27">2026-11-27</time></p><p>张鑫旭记录了第一次直接用AI读Figma设计稿生成网页的实践：紧急活动需求下午到、后天上线，需同时支持移动端与桌面端，项目里的.mcp.json已有同事配置好figma，CodeBuddy自动识别。结论是效率确实提升很多倍，但仍有不足。对读者：设计稿转代码的MCP链路已可用于赶工期场景，但要预留人工校对环节，尤其是响应式与细节还原。</p><p class="news-entry-source"><a href="https://www.zhangxinxu.com/wordpress/2026/11/ai-figma-mcp/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const w=a(s,[["render",i]]);export{m as __pageData,w as default};
